// TH16 v1.00a Extra (Stage 7) final boss, non-spell "Boss2" (st07bs.ecl.txt:218-277).
// Scope: Boss2 entry only; interrupt window setInterrupt(0, 2000, 3600, "BossCard2").
// Entrance clears/items/spell/UI/presentation are omitted per TH16 transcription policy;
// the entrance state is reproduced as an invulnerable boss spawned at (0,128).

const TIME_LIMIT: int = 3724;       // 120 shell buffer + 3600 source window + 4 startup slack
const OPENING_BUFFER: int = 120;    // validation.md shell buffer, separate from source waits
const TH16_SHARD: int = 512;        // etSprite type 10 (bullet-types.md)
const SHARD_COLOR: int = 6;         // etSprite(0, 10, 6)
const BOSS_START_X: fx = 0fx;       // Boss init movePos(0,128); Boss2 movePosTime(0,128)
const BOSS_START_Y: fx = 128fx;
const ET_OFFSET_X: fx = 0fx;        // etOffset(0, 0, -24)
const ET_OFFSET_Y: fx = -24fx;
const ET_DIST: fx = 32fx;           // etDist(0, 32)

// Boss2_at dependency (st07bs.ecl.txt:279-302).
// 100 fires of mode3 (fixed-direction ring), etCount(1,5) => N=1 route x M=5 layers.
// Layer q angle = alpha + q*B, speed = v0 + (v1-v0)*q/(M-1) = 4.5 - 0.375*q.
// Birth position = enemy+offset, pushed ET_DIST along the layer angle, then the exercised
// ANIM a=1 backward displacement -4*velocity => net distance ET_DIST - 4*speed.
async sub boss2_at(a: angle, b: angle) {
    var base: angle = aim_player();     // %C = %ANGLE_PLAYER (enemy toward player, once)
    var bi: int = b as int;             // per-layer angle step, BAM int
    for wave in 0..100 {                // $D = 100
        var ox: fx = $self_x + ET_OFFSET_X;
        var oy: fx = $self_y + ET_OFFSET_Y;
        for q in 0..5 {                 // layer q = 0..M-1
            var ang: angle = base + ((q * bi) as angle);
            var spd: fx = 4.5fx - (q as fx) * 0.375fx;
            var d: fx = ET_DIST - 4fx * spd;
            _ = fire(TH16_SHARD, SHARD_COLOR,
                     ox + d * cos(ang), oy + d * sin(ang),
                     spd, ang, none, none);
        }
        base = base + a;                // %C = %C + %A (after etAngle captured old base)
        wait(3);                        // source wait(3)
    }
}

// moveRand(60, 4, 1.9) with moveLimit(0,128,240,64) (movement.md BossCard2 recipe, speed 1.9).
// Direction inner zone x in [-60,60], y in [112,144]; actual clamp x [-120,120], y [96,160].
// int slot 0 = next-step count; fx slots 0/1 = logical unit vector.
sub arm_next_step() {
    var k: int = self_int(0) + 1;
    set_self_int(0, k);
    var speed: fx = 0fx;
    if k < 60 { speed = ((60 - k) as fx) * 1.9fx / 60fx; }
    var nx: fx = $self_x + self_fx(0) * speed;
    var ny: fx = $self_y + self_fx(1) * speed;
    if nx < -120fx { nx = -120fx; }
    if nx > 120fx { nx = 120fx; }
    if ny < 96fx { ny = 96fx; }
    if ny > 160fx { ny = 160fx; }
    move_vel_xy(0, nx - $self_x, ny - $self_y, EASE_LINEAR);
}
sub begin_angle(a: angle) {
    set_self_fx(0, cos(a));
    set_self_fx(1, sin(a));
    set_self_int(0, 0);
    arm_next_step();
}
sub move_rand() {
    var r: int = rand(65536) - 32768;
    var a: int = r / 3;
    if $self_x < -60fx {
        a = r / 3;
    } else if $self_x > 60fx {
        a = r / 3 + 32768;
        if a > 32768 { a = a - 65536; }
    } else {
        a = r / 4;
        var choose: int = rand(65536) % 3;
        if $player_x > $self_x {
            if choose == 0 { a = a + 32768; }
        } else {
            if choose != 0 { a = a + 32768; }
        }
    }
    if $self_y < 112fx {
        if a < 0 { a = -a; }
    } else if $self_y > 144fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    // Native +/-pi/2 guard, epsilon 0.05 rad ~= 522 BAM (unreachable here, kept for fidelity).
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    begin_angle(a as angle);
}
sub move_wait(frames: int) {
    for i in 0..frames {
        wait(1);
        arm_next_step();
    }
}

async sub boss2_main() {
    // Real boss: invulnerable; source boxes setHurtbox(40,40)->r20, setHitbox(48,48)->r24.
    set_invuln(65535);
    set_hitbox(24fx);
    set_hurtbox(20fx);
    // Entry moveVel(0,0)/moveVelTime/movePosTime clear residual motion; spawned stationary.
    // Source movePosTime(60,4,0,128) ends at the spawn point (0,128) and is a no-op here.
    wait(120);                       // source wait(120)
    // moveLimit(0,128,240,64): the box is enforced per step inside arm_next_step.
    wait(60);                        // source wait(60)
    loop {                           // Boss2_1176 .. Boss2_1408 (infinite until timeout)
        spawn boss2_at(8deg, 91bam);
        wait(100);
        move_rand();                 // moveRand(60, 4, 1.9f)
        move_wait(60);
        spawn boss2_at(-8deg, -91bam);
        wait(100);
        move_rand();
        move_wait(60);
    }
}

async sub boss2_pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(BOSS_START_X, BOSS_START_Y, 13000, 0, 0, 0, boss2_main);
}

async sub boss2_control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, boss2_pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, boss2_control);
    loop { wait(600); }
}
